    parent: "RU",
    type: "city",
    name: { de: "Jekaterinburg", hu: "Jekatyerinburg", ro: "Ekaterinburg", en: "Yekaterinburg"},
    image: "/poi-images/russia-yekaterinburg-cities-v2.webp",
