    parent: "RU",
    type: "city",
    name: { de: "Krasnojarsk", hu: "Krasznojarszk", ro: "Krasnoiarsk", en: "Krasnoyarsk"},
    image: "/poi-images/russia-krasnoyarsk-cities-v2.webp",
